-- 0034_qm_bop_seed.sql
-- Quantities module: seed the Hawalli contract-9 Bill of Prices (جدول الاسعار - حولي).
-- Source: the standalone BOP workbook, sheet 'bill' (1,310 id rows).
-- Parsed with the bidi-safe importer (raw ids are band/bab; bab resolved by
-- validating against the known bab set {1,2,3,4,5,6,7,12,14,17,22} + run position).
-- 4 rows carry positional corrections (see source_note on the row + the
-- validation report in the module brief delivery); 1 blank id-only row skipped (104/12).
-- Idempotent: on conflict do nothing against the (contract, bab, band, suffix) key.

do $$
declare
  v_contract bigint;
begin
  select id into v_contract from qm_contracts where code = 'HAW9';
  if v_contract is null then
    raise exception 'qm_contracts HAW9 missing - run 0033 first';
  end if;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

  on conflict (contract_id, bab, band, coalesce(suffix, '')) do nothing;

end $$;
